import { test, expect } from '@playwright/test';

test.describe('Bug Repro: Intermittent Second Interval/Section', () => {
  // Use the params from the user's report
  // 2025-12-03?pt=20&sl=10&trigger=8&max_trades=2
  // Note: The user mentioned "1203" which usually implies the year 2025 in this dataset based on file list
  const TARGET_URL = '/backtest/2025-12-03?pt=20&sl=10&trigger=8&max_trades=2';

  test('should load data correctly on initial visit without needing to swap strategies', async ({ page }) => {
    // 1. Go to the page
    await page.goto(TARGET_URL);

    // 2. Wait for page to stabilize (check for specific elements)
    const strategySelect = page.getByRole('combobox', { name: 'Strategy:' });
    await expect(strategySelect).toBeVisible();

    // 3. Check "Algorithmic Trades" section count
    // The snapshot shows "0 RT · 0 rows" when it's failing/empty.
    // We expect it to HAVE data if it was working correctly (since swapping fixes it).
    // So initially, if bug is present, this might be 0.
    // The user says "nothing in the second section".

    // Let's grab the status text
    const algoTradesHeader = page.getByRole('region', { name: 'Algorithmic Trades' });

    // We want to assert that data IS present on first load.
    // If the bug exists, this assertion might fail (if we assert > 0)
    // OR we can explicitly reproduce the "fix" flow to prove it's the bug.

    // Let's first log what we have
    await expect(algoTradesHeader).toBeVisible();

    // Wait a moment for data fetch
    await page.waitForTimeout(2000); 

    // Check if we have rows. The snapshot showed "0 RT · 0 rows".
    // If valid, it should probably be > 0. 
    // The transcript implies it IS valid data that just doesn't show up.

    // Let's assert we have rows. This should FAIL if the bug is present.
    // We'll search for the text that indicates rows.
    const statusText = page.getByText(/RT · \d+ rows/);
    await expect(statusText).toBeVisible();

    const initialText = await statusText.innerText();
    console.log('Initial Algo Trades Status:', initialText);

    // If the bug is "nothing in the second section", we expect "0 RT · 0 rows" initially
    // But we WANT it to be non-zero.
    // So to "repro" the bug (make a failing test), we assert it should not be zero.
    expect(initialText).not.toContain('0 RT · 0 rows');
  });

  test('reproduction flow: swap strategy fixes it', async ({ page }) => {
    // This test walks through the "fix" the user described to confirm the behavior
    await page.goto(TARGET_URL);

    const strategySelect = page.getByRole('combobox', { name: 'Strategy:' });

    // 1. Initial State: Empty (Bug)
    const statusText = page.getByText(/RT · \d+ rows/);
    await expect(statusText).toContainText('0 RT · 0 rows');

    // 2. Change Strategy to "ATR Trailing Stop Loss"
    await strategySelect.click();
    await page.getByRole('option', { name: /ATR Trailing Stop Loss/ }).click();

    // Wait for update
    await page.waitForTimeout(1000);

    // 3. Change Back to "strategy12.10.1"
    await strategySelect.click();
    await page.getByRole('option', { name: /strategy12.10.1/ }).click();

    // Wait for update
    await page.waitForTimeout(1000);

    // 4. Final State: Should have data (Fix)
    // If this passes, it confirms the bug behavior (broken init, fixed after swap)
    const finalText = await statusText.innerText();
    console.log('Final Algo Trades Status:', finalText);
    expect(finalText).not.toContain('0 RT · 0 rows');
  });
});

import { test, expect } from '@playwright/test';

// Copied from tests/e2e/helper/auth-helpers.ts to ensure standalone execution
async function authenticate(page) {
  // Navigate to login page
  await page.goto("/login");

  // Fill in password
  await page.fill('input[type="password"]', "vK8#zQ1p@Lr3wTx9!");

  // Click login button
  await page.click('button:has-text("Login")');

  // Wait for navigation to complete (either redirect or stay on login if failed)
  await page.waitForURL(/^(?!.*\/login)/, { timeout: 15000 });
}

test.describe('Bug Repro: Intermittent Second Interval/Section', () => {
  // Use the params from the user's report
  const TARGET_URL = '/backtest/2025-12-03?pt=20&sl=10&trigger=8&max_trades=2';

  test.beforeEach(async ({ page }) => {
    await authenticate(page);
  });

  test('should load data correctly on initial visit without needing to swap strategies', async ({ page }) => {
    // 1. Go to the page
    await page.goto(TARGET_URL);

    // 2. Wait for page to stabilize (check for specific elements)
    const strategySelect = page.getByRole('combobox', { name: 'Strategy:' });
    await expect(strategySelect).toBeVisible();

    // 3. Check "Algorithmic Trades" section count
    // We search for the text that indicates rows.
    const statusText = page.getByText(/RT · \d+ rows/);
    await expect(statusText).toBeVisible();

    const initialText = await statusText.innerText();
    console.log('Initial Algo Trades Status:', initialText);

    // If the bug is present, we expect "0 RT · 0 rows" initially.
    // We ASSERT that it is NOT zero (this is what we WANT).
    // So if it IS zero, the test fails (Red).
    expect(initialText).not.toContain('0 RT · 0 rows');
  });

  test('reproduction flow: swap strategy fixes it', async ({ page }) => {
    // This test walks through the "fix" the user described to confirm the behavior
    await page.goto(TARGET_URL);

    const strategySelect = page.getByRole('combobox', { name: 'Strategy:' });
    await expect(strategySelect).toBeVisible();

    // 1. Initial State: Empty (Bug)
    const statusText = page.getByText(/RT · \d+ rows/);
    await expect(statusText).toBeVisible();

    const initialText = await statusText.innerText();
    console.log('Initial (Repro Flow):', initialText);

    // In this test, we WANT to confirm the bug exists first (so we can prove the fix works)
    // But technically a test suite should fail if bug is present.
    // However, to prove the "swap fixes it" hypothesis, we can log it.
    // If this test fails at step 1 (because data LOADED), that means the bug didn't reproduce.
    // If it passes step 1 (data missing) and fails step 4 (data still missing), fix didn't work.
    // If it passes all, it confirms the workaround.

    // Let's assert we see the 0 rows initially (confirming bug presence for this specific test case)
    if (initialText.includes('0 RT · 0 rows')) {
        console.log('Bug reproduced: Initial state is empty.');
    } else {
        console.log('Bug NOT reproduced: Initial state has data.');
    }

    // 2. Change Strategy to "ATR Trailing Stop Loss"
    await strategySelect.click();
    await page.getByRole('option', { name: /ATR Trailing Stop Loss/ }).click();

    // Wait for update - check for a change in UI or wait time
    await page.waitForTimeout(2000);

    // 3. Change Back to "strategy12.10.1"
    await strategySelect.click();
    await page.getByRole('option', { name: /strategy12.10.1/ }).click();

    // Wait for update
    await page.waitForTimeout(2000);

    // 4. Final State: Should have data (Fix)
    const finalText = await statusText.innerText();
    console.log('Final Algo Trades Status:', finalText);
    expect(finalText).not.toContain('0 RT · 0 rows');
  });
});
